 * Type definitions for the Calendar Viewer component.
 * These extend the base API types with UI-specific properties.
 */

// ============================================================================
// Enums / Literal Types
// ============================================================================

export type CalendarOperation = 'create' | 'update' | 'delete';
export type RecurrenceScope = 'this' | 'this_and_future' | 'all';
export type AttendeeResponse = 'accepted' | 'declined' | 'tentative' | 'needs-action';
export type EventStatus = 'confirmed' | 'tentative' | 'cancelled';
export type EventVisibility = 'public' | 'private' | 'default';
export type EventTransparency = 'opaque' | 'transparent';
export type ReminderType = 'notification' | 'email' | 'both';
export type RecurrenceFrequency = 'daily' | 'weekly' | 'monthly' | 'yearly';
export type RecurrenceEndType = 'never' | 'until' | 'count';
export type DayOfWeek = 'monday' | 'tuesday' | 'wednesday' | 'thursday' | 'friday' | 'saturday' | 'sunday';

// ============================================================================
// Calendar View Types
// ============================================================================

export type CalendarViewMode = 'month' | 'week' | '3-day' | 'day';

// ============================================================================
// Backend Model Types
// ============================================================================

/**
 * Event attendee.
 */
export interface Attendee {
  email: string;
  display_name?: string | null;
  optional: boolean;
  response: AttendeeResponse;
  comment?: string | null;
}

/**
 * Recurrence rule for repeating events.
 */
export interface RecurrenceRule {
  frequency: RecurrenceFrequency;
  interval: number;
  days_of_week?: DayOfWeek[] | null;
  day_of_month?: number | null;
  month_of_year?: number | null;
  end_type: RecurrenceEndType;
  end_date?: string | null;
  count?: number | null;
}

/**
 * Event reminder.
 */
export interface Reminder {
  minutes_before: number;
  type: ReminderType;
}

/**
 * Event attachment.
 */
export interface Attachment {
  filename: string;
  size: number;
  mime_type: string;
  url?: string | null;
  attachment_id: string;
}

/**
 * A calendar container for events.
 */
export interface Calendar {
  calendar_id: string;
  name: string;
  color: string;
  visible: boolean;
  created_at: string;
  updated_at: string;
  event_ids: string[];
  default_reminders: Reminder[];
}

/**
 * A calendar event with all metadata.
 */
export interface CalendarEvent {
  event_id: string;
  calendar_id: string;
  title: string;
  start: string;
  end: string;
  all_day: boolean;
  timezone: string;
  description?: string | null;
  location?: string | null;
  status: EventStatus;
  organizer?: string | null;
  attendees: Attendee[];
  recurrence?: RecurrenceRule | null;
  recurrence_exceptions: string[];
  recurrence_id?: string | null;
  parent_event_id?: string | null;
  reminders: Reminder[];
  color?: string | null;
  visibility: EventVisibility;
  transparency: EventTransparency;
  attachments: Attachment[];
  conference_link?: string | null;
  created_at: string;
  updated_at: string;
  deleted_at?: string | null;
}

/**
 * Complete calendar state from the backend.
 */
export interface CalendarState {
  modality_type: string;
  last_updated: string;
  update_count: number;
  default_calendar_id: string;
  user_timezone: string;
  calendars: Record<string, Calendar>;
  events: Record<string, CalendarEvent>;
  calendar_count: number;
  event_count: number;
}

// ============================================================================
// API Request Types
// ============================================================================

/**
 * Request to create a new calendar event.
 */
export interface CreateCalendarEventRequest {
  calendar_id?: string;
  title: string;
  description?: string | null;
  start: string;
  end: string;
  all_day?: boolean;
  timezone?: string;
  location?: string | null;
  status?: EventStatus;
  organizer?: string | null;
  attendees?: Attendee[] | null;
  recurrence?: RecurrenceRule | null;
  recurrence_exceptions?: string[] | null;
  reminders?: Reminder[] | null;
  color?: string | null;
  visibility?: EventVisibility;
  transparency?: EventTransparency;
  attachments?: Attachment[] | null;
  conference_link?: string | null;
}

/**
 * Request to update an existing calendar event.
 */
export interface UpdateCalendarEventRequest {
  event_id: string;
  calendar_id?: string;
  recurrence_scope?: RecurrenceScope;
  title?: string | null;
  description?: string | null;
  start?: string | null;
  end?: string | null;
  all_day?: boolean | null;
  timezone?: string | null;
  location?: string | null;
  status?: EventStatus | null;
  organizer?: string | null;
  attendees?: Attendee[] | null;
  recurrence?: RecurrenceRule | null;
  recurrence_exceptions?: string[] | null;
  recurrence_id?: string | null;
  reminders?: Reminder[] | null;
  color?: string | null;
  visibility?: EventVisibility | null;
  transparency?: EventTransparency | null;
  attachments?: Attachment[] | null;
  conference_link?: string | null;
}

/**
 * Request to delete a calendar event.
 */
export interface DeleteCalendarEventRequest {
  event_id: string;
  calendar_id?: string;
  recurrence_scope?: RecurrenceScope;
  recurrence_id?: string | null;
}

/**
 * Request to query calendar events.
 */
export interface CalendarQueryRequest {
  calendar_ids?: string[] | null;
  start?: string | null;
  end?: string | null;
  search?: string | null;
  status?: EventStatus | null;
  has_attendees?: boolean | null;
  recurring?: boolean | null;
  expand_recurring?: boolean;
  limit?: number | null;
  offset?: number;
  sort_by?: string;
  sort_order?: string;
}

// ============================================================================
// UI Types
// ============================================================================

/**
 * Event display item for calendar grid.
 */
export interface EventDisplayItem {
  event: CalendarEvent;
  calendar: Calendar;
  displayColor: string;
  isMultiDay: boolean;
  startDate: Date;
  endDate: Date;
}

/**
 * Time slot for click-to-schedule.
 */
export interface TimeSlot {
  date: Date;
  hour?: number;
  minute?: number;
}

/**
 * Form data for creating/editing events.
 */
export interface EventFormData {
  title: string;
  calendar_id: string;
  all_day: boolean;
  start_date: string;
  start_time: string;
  end_date: string;
  end_time: string;
  timezone: string;
  location: string;
  description: string;
  conference_link: string;
  recurrence: RecurrenceRule | null;
  reminders: Reminder[];
  attendees: Attendee[];
  color: string | null;
  status: EventStatus;
  visibility: EventVisibility;
}

/**
 * Calendar color preset.
 */
export interface ColorPreset {
  name: string;
  value: string;
}

/**
 * Default color presets for calendars.
 */
export const CALENDAR_COLORS: ColorPreset[] = [
  { name: 'Blue', value: '#4285f4' },
  { name: 'Red', value: '#ea4335' },
  { name: 'Yellow', value: '#fbbc04' },
  { name: 'Green', value: '#34a853' },
  { name: 'Purple', value: '#9c27b0' },
  { name: 'Pink', value: '#e91e63' },
  { name: 'Teal', value: '#009688' },
  { name: 'Orange', value: '#ff9800' },
  { name: 'Indigo', value: '#3f51b5' },
  { name: 'Cyan', value: '#00bcd4' },
];

/**
 * Timezone presets for quick selection.
 */
export const TIMEZONE_PRESETS = [
  'UTC',
  'America/New_York',
  'America/Chicago',
  'America/Denver',
  'America/Los_Angeles',
  'Europe/London',
  'Europe/Paris',
  'Europe/Berlin',
  'Asia/Tokyo',
  'Asia/Shanghai',
  'Australia/Sydney',
];
"}

{"content": "/**
 * Calendar toolbar component.
 * Provides navigation, view switching, and action buttons.
 */
import { Button } from '@/components/ui/button';
import { Separator } from '@/components/ui/separator';
import {
  Tooltip,
  TooltipContent,
  TooltipProvider,
  TooltipTrigger,
} from '@/components/ui/tooltip';
import {
  ToggleGroup,
  ToggleGroupItem,
} from '@/components/ui/toggle-group';
import {
  ChevronLeft,
  ChevronRight,
  Plus,
  Settings,
  RefreshCw,
  CalendarDays,
  CalendarRange,
  Calendar as CalendarIcon,
  LayoutGrid,
} from 'lucide-react';
import type { CalendarViewMode } from './types';

interface CalendarToolbarProps {
  /** Current view mode */
  viewMode: CalendarViewMode;
  /** Callback when view mode changes */
  onViewModeChange: (mode: CalendarViewMode) => void;
  /** Currently displayed date (for title) */
  currentDate: Date;
  /** Callback to go to previous period */
  onPrevious: () => void;
  /** Callback to go to next period */
  onNext: () => void;
  /** Callback to go to today */
  onToday: () => void;
  /** Callback to create a new event */
  onCreateEvent: () => void;
  /** Callback to open settings */
  onOpenSettings: () => void;
  /** Callback to refresh calendar data */
  onRefresh: () => void;
  /** Whether data is currently refreshing */
  isRefreshing?: boolean;
  /** Event count summary */
  eventCount?: number;
}

/**
 * Format the date range title based on view mode.
 */
function formatDateTitle(date: Date, viewMode: CalendarViewMode): string {
  const options: Intl.DateTimeFormatOptions = { year: 'numeric' };

  switch (viewMode) {
    case 'month':
      return date.toLocaleDateString('en-US', { month: 'long', year: 'numeric' });
    case 'week': {
      // Get the start and end of the week
      const weekStart = new Date(date);
      weekStart.setDate(date.getDate() - date.getDay());
      const weekEnd = new Date(weekStart);
      weekEnd.setDate(weekStart.getDate() + 6);

      const startMonth = weekStart.toLocaleDateString('en-US', { month: 'short', day: 'numeric' });
      const endMonth = weekEnd.toLocaleDateString('en-US', { month: 'short', day: 'numeric', year: 'numeric' });
      return `${startMonth} - ${endMonth}`;
    }
    case '3-day': {
      const endDate = new Date(date);
      endDate.setDate(date.getDate() + 2);
      const start = date.toLocaleDateString('en-US', { month: 'short', day: 'numeric' });
      const end = endDate.toLocaleDateString('en-US', { month: 'short', day: 'numeric', year: 'numeric' });
      return `${start} - ${end}`;
    }
    case 'day':
      return date.toLocaleDateString('en-US', { 
        weekday: 'long', 
        month: 'long', 
        day: 'numeric', 
        year: 'numeric' 
      });
  }
}

/**
 * Icon button with tooltip.
 */
function ToolbarButton({
  icon: Icon,
  label,
  onClick,
  disabled,
  variant = 'ghost',
}: {
  icon: React.ComponentType<{ className?: string }>;
  label: string;
  onClick: () => void;
  disabled?: boolean;
  variant?: 'ghost' | 'default' | 'outline';
}) {
  return (
    <TooltipProvider>
      <Tooltip>
        <TooltipTrigger asChild>
          <Button
            variant={variant}
            size="sm"
            onClick={onClick}
            disabled={disabled}
            className="h-8"
          >
            <Icon className="h-4 w-4" />
          </Button>
        </TooltipTrigger>
        <TooltipContent>
          <p>{label}</p>
        </TooltipContent>
      </Tooltip>
    </TooltipProvider>
  );
}

export function CalendarToolbar({
  viewMode,
  onViewModeChange,
  currentDate,
  onPrevious,
  onNext,
  onToday,
  onCreateEvent,
  onOpenSettings,
  onRefresh,
  isRefreshing,
  eventCount,
}: CalendarToolbarProps) {
  return (
    <div className="flex flex-col gap-2 p-2 border-b bg-background">
      {/* Top row: Navigation and view switcher */}
      <div className="flex items-center justify-between">
        {/* Left side: Navigation */}
        <div className="flex items-center gap-2">
          <ToolbarButton
            icon={ChevronLeft}
            label="Previous"
            onClick={onPrevious}
          />
          <Button 
            variant="outline" 
            size="sm" 
            onClick={onToday}
            className="h-8"
          >
            Today
          </Button>
          <ToolbarButton
            icon={ChevronRight}
            label="Next"
            onClick={onNext}
          />

          <Separator orientation="vertical" className="h-6 mx-2" />

          {/* Date title */}
          <h2 className="text-lg font-semibold min-w-[200px]">
            {formatDateTitle(currentDate, viewMode)}
          </h2>
        </div>

        {/* Right side: View mode toggle */}
        <div className="flex items-center gap-2">
          <ToggleGroup 
            type="single" 
            value={viewMode} 
            onValueChange={(value) => value && onViewModeChange(value as CalendarViewMode)}
            className="border rounded-md"
          >
            <ToggleGroupItem value="month" aria-label="Month view" className="h-8 px-3">
              <LayoutGrid className="h-4 w-4 mr-1" />
              Month
            </ToggleGroupItem>
            <ToggleGroupItem value="week" aria-label="Week view" className="h-8 px-3">
              <CalendarRange className="h-4 w-4 mr-1" />
              Week
            </ToggleGroupItem>
            <ToggleGroupItem value="3-day" aria-label="3-Day view" className="h-8 px-3">
              <CalendarDays className="h-4 w-4 mr-1" />
              3-Day
            </ToggleGroupItem>
            <ToggleGroupItem value="day" aria-label="Day view" className="h-8 px-3">
              <CalendarIcon className="h-4 w-4 mr-1" />
              Day
            </ToggleGroupItem>
          </ToggleGroup>

          <ToolbarButton
            icon={RefreshCw}
            label="Refresh"
            onClick={onRefresh}
            disabled={isRefreshing}
          />
        </div>
      </div>

      {/* Bottom row: Actions and status */}
      <div className="flex items-center justify-between">
        <div className="flex items-center gap-2">
          <Button 
            onClick={onCreateEvent}
            size="sm"
            className="h-8"
          >
            <Plus className="h-4 w-4 mr-1" />
            Create Event
          </Button>

          <ToolbarButton
            icon={Settings}
            label="Calendar Settings"
            onClick={onOpenSettings}
            variant="outline"
          />
        </div>

        {/* Status */}
        {eventCount !== undefined && (
          <span className="text-sm text-muted-foreground">
            {eventCount} event{eventCount !== 1 ? 's' : ''} in view
          </span>
        )}
      </div>
    </div>
  );
}
